using System.Collections;
using System.Reflection;
using KingdomEnhancedMod;
using UnityEngine;
using Scope=KingdomEnhancedMod.GreekScaleScope;
using BagPatch=KingdomEnhancedMod.PatchEconomy_CurrencyBag;

static class Program
{
 static int passed,failed;
 static void Eq(float expected,float actual,string why="scale"){if(MathF.Abs(expected-actual)>.00001f)throw new Exception($"{why}: expected {expected}, got {actual}");}
 static void True(bool value,string why){if(!value)throw new Exception(why);}
 static void Vector(Vector3 expected,Vector3 actual){for(int a=0;a<3;a++)Eq(expected[a],actual[a],"axis "+a);}
 static int RegistryCount()=>((IDictionary)typeof(Scope).GetField("Requests",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null)).Count;
 static void World(int index){BiomeHolder.Inst=new(){BiomeIndex=index};Scope.Tick();}
 static void Test(string name,Action body)
 {
  ((IDictionary)typeof(Scope).GetField("Requests",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null)).Clear();
  ModConfig.Enabled=new();BiomeHolder.Inst=new();Managers.Inst=new();BiomeData.Swap=null;Time.frameCount+=500;Scope.Tick();
  try{body();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}
 }
 static CurrencyBag Bag(Vector3? nativeRoot=null,Vector3? nativeContainer=null)
 {
  var b=new GameObject().AddComponent<CurrencyBag>();b.transform.localScale=nativeRoot??Vector3.one;
  b._container=new GameObject().transform;b._container.localScale=nativeContainer??Vector3.one;return b;
 }
 static BagCurrency Coin(CurrencyBag bag,Vector3 incoming,Vector3? nativePrefab=null,CurrencyType type=CurrencyType.Coins)
 {
  var prefab=new GameObject().AddComponent<BagCurrency>();prefab.transform.localScale=nativePrefab??Vector3.one;
  Managers.Inst.currency.Data[type]=new(){BagPrefab=prefab};
  var coin=new GameObject().AddComponent<BagCurrency>();coin.bag=bag;coin.CurrencyType=type;coin.transform.localScale=incoming;return coin;
 }
 static Vector3 Mul(Vector3 a,Vector3 b)=>new(a.x*b.x,a.y*b.y,a.z*b.z);
 static void ScaleBag(CurrencyBag bag)=>BagPatch.SetCurrencyBag_Postfix(bag);
 static bool Reset(BagCurrency coin,int nth=1){bool stack=false;BagPatch.ResetVisuals_Prefix(coin,false,nth,ref stack);return stack;}
 static void Main()
 {
  Test("fresh inherited coin 2 restores native1 in every world",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));Reset(c);Vector(Vector3.one,c.transform.localScale);World(1);Vector(Vector3.one,c.transform.localScale);Vector(new(2,2,1),b.transform.localScale);Vector(new(.5f,.5f,1),b._container.localScale);});
  Test("repeat Reset and reuse never divide coin to .5",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));for(int i=0;i<5;i++)Reset(c);World(1);Vector(Vector3.one,c.transform.localScale);World(3);for(int i=0;i<5;i++)Reset(c);World(1);Vector(Vector3.one,c.transform.localScale);});
  Test("nonunit signed bag composition equals native root times swapped prefab",()=>{var b=Bag(new(-.8f,1.2f,1.5f),new(-2,1.5f,2));ScaleBag(b);var c=Coin(b,new(.8f,1.6f,.3f));var swap=new GameObject().AddComponent<BagCurrency>();swap.transform.localScale=new(-.8f,1.2f,.6f);BiomeData.Swap=swap;Reset(c);Vector(new(-1.6f,2.4f,1.5f),b.transform.localScale);Vector(new(-1f,.75f,2),b._container.localScale);Vector(new(.4f,.8f,.3f),c.transform.localScale);Vector(new(.64f,1.44f,.9f),Mul(Mul(b.transform.localScale,b._container.localScale),c.transform.localScale));World(1);Vector(new(-1.6f,2.4f,1.5f),b.transform.localScale);Vector(new(-1f,.75f,2),b._container.localScale);Vector(new(.4f,.8f,.3f),c.transform.localScale);World(3);Vector(new(.4f,.8f,.3f),c.transform.localScale);});
  Test("inherited coin corrected in non-Greek and after off-on",()=>{World(1);var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));int writes=c.transform.Writes;Reset(c);Vector(Vector3.one,c.transform.localScale);Eq(writes+1,c.transform.Writes,"one correction");for(int i=0;i<4;i++)Reset(c);Eq(writes+1,c.transform.Writes,"idempotent");ModConfig.Enabled.Value=false;Scope.Tick();Vector(Vector3.one,c.transform.localScale);ModConfig.Enabled.Value=true;Scope.Tick();Vector(Vector3.one,c.transform.localScale);World(3);Vector(Vector3.one,c.transform.localScale);});
  Test("mismatched inherited coin is left untouched in every world",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(1.7f,1.7f,1));int writes=c.transform.Writes;Reset(c);Eq(writes,c.transform.Writes,"no guess");Vector(new(1.7f,1.7f,1),c.transform.localScale);World(1);Vector(new(1.7f,1.7f,1),c.transform.localScale);World(3);Vector(new(1.7f,1.7f,1),c.transform.localScale);});
  Test("coin created while disabled stays untouched after enable",()=>{World(1);ModConfig.Enabled.Value=false;Scope.Tick();var b=Bag(new(.7f,1.3f,1),new(2,1.5f,1));ScaleBag(b);var c=Coin(b,new(1,1,1));int writes=c.transform.Writes;Reset(c);Eq(writes,c.transform.Writes,"disabled reset no write");ModConfig.Enabled.Value=true;Scope.Tick();Vector(Vector3.one,c.transform.localScale);Eq(writes,c.transform.Writes,"pre-enable coin not claimed");Reset(c);Eq(writes,c.transform.Writes,"no inheritance evidence after enable");Vector(Vector3.one,c.transform.localScale);});
  Test("repeated Awake and Set on one bag do not compound",()=>{var b=Bag(new(.7f,1.3f,1),new(2,1.5f,1));for(int i=0;i<5;i++){BagPatch.Awake_Postfix(b);ScaleBag(b);}Vector(new(1.4f,2.6f,1),b.transform.localScale);Vector(new(1,.75f,1),b._container.localScale);ModConfig.Enabled.Value=false;Scope.Tick();Vector(new(.7f,1.3f,1),b.transform.localScale);Vector(new(2,1.5f,1),b._container.localScale);});
  Test("external wallet axes survive disable while untouched axes restore",()=>{var b=Bag();ScaleBag(b);b.transform.localScale=new(5,2,1);b._container.localScale=new(.5f,3,1);ModConfig.Enabled.Value=false;Scope.Tick();Vector(new(5,1,1),b.transform.localScale);Vector(new(1,3,1),b._container.localScale);});
  Test("zero native container axis never claims a coin",()=>{var b=Bag(nativeContainer:new(0,1.5f,1));ScaleBag(b);var c=Coin(b,new(2,2,2));int writes=c.transform.Writes;Reset(c);Eq(writes,c.transform.Writes,"zero denominator no write");Vector(new(2,2,2),c.transform.localScale);});
  Test("missing coin container is not guessed",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,2));b._container=null;int writes=c.transform.Writes;Reset(c);Eq(writes,c.transform.Writes,"no container no write");Vector(new(2,2,2),c.transform.localScale);});
  Test("nonfinite native bag scale is not written",()=>{var b=Bag(new(float.NaN,1,1));int rw=b.transform.Writes,cw=b._container.Writes;ScaleBag(b);Eq(rw,b.transform.Writes,"root untouched");Eq(cw,b._container.Writes,"container untouched");});
  Test("wallet remains active with negative biome index",()=>{var b=Bag();ScaleBag(b);World(-1);var c=Coin(b,new(2,2,1));int writes=c.transform.Writes;Reset(c);Vector(Vector3.one,c.transform.localScale);Eq(writes+1,c.transform.Writes,"all-world claim");Vector(new(.5f,.5f,1),b._container.localScale);});
  Test("missing currency source changes no coin and stacklimit remains600",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));Managers.Inst.currency.Missing=true;int writes=c.transform.Writes;True(Reset(c,599),"stack599");True(!Reset(c,600),"no stack600");Eq(writes,c.transform.Writes,"source unavailable failclosed");});
  Test("null biome source preserves existing ownership until known world",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));Reset(c);BiomeHolder.Inst=null;Scope.Tick();int writes=c.transform.Writes;True(Reset(c,599),"stack remains");Eq(writes,c.transform.Writes,"no source no write");World(1);Vector(Vector3.one,c.transform.localScale);});
  Test("two bags with signed containers and distinct prefabs stay independent",()=>{World(1);var a=Bag(new(-.8f,1.2f,1),new(-2,1.5f,2));ScaleBag(a);var ca=Coin(a,new(.8f,1.6f,.3f),new(-.8f,1.2f,.6f),CurrencyType.Coins);Reset(ca);var b=Bag(new(1.4f,-.9f,.7f),new(2,.5f,-1.5f));ScaleBag(b);var cb=Coin(b,new(1.6f,2.4f,-.2f),new(1.6f,.6f,.3f),CurrencyType.Shades);Reset(cb);Vector(new(-1.6f,2.4f,1),a.transform.localScale);Vector(new(-1f,.75f,2),a._container.localScale);Vector(new(.4f,.8f,.3f),ca.transform.localScale);Vector(new(2.8f,-1.8f,.7f),b.transform.localScale);Vector(new(1,.25f,-1.5f),b._container.localScale);Vector(new(.8f,1.2f,-.2f),cb.transform.localScale);Vector(new(.64f,1.44f,.6f),Mul(Mul(a.transform.localScale,a._container.localScale),ca.transform.localScale));Vector(new(2.24f,-.54f,.21f),Mul(Mul(b.transform.localScale,b._container.localScale),cb.transform.localScale));});
  Test("two bag types restore together only when the mod is disabled",()=>{var a=Bag(new(-.8f,1.2f,1));var b=Bag(new(1.4f,-.9f,.7f));ScaleBag(a);ScaleBag(b);ScaleBag(a);Vector(new(-1.6f,2.4f,1),a.transform.localScale);Vector(new(2.8f,-1.8f,.7f),b.transform.localScale);World(1);Vector(new(-1.6f,2.4f,1),a.transform.localScale);Vector(new(2.8f,-1.8f,.7f),b.transform.localScale);ModConfig.Enabled.Value=false;Scope.Tick();Vector(new(-.8f,1.2f,1),a.transform.localScale);Vector(new(1.4f,-.9f,.7f),b.transform.localScale);});
  Test("null config registers wallet desired without writing",()=>{ModConfig.Enabled=null;Scope.Tick();var b=Bag();int rw=b.transform.Writes,cw=b._container.Writes;ScaleBag(b);Eq(rw,b.transform.Writes,"unknown root unwritten");Eq(cw,b._container.Writes,"unknown container unwritten");Scope.Tick();Eq(rw,b.transform.Writes,"tick unknown unwritten");ModConfig.Enabled=new(){Value=false};Scope.Tick();Eq(rw,b.transform.Writes,"disabled unwritten");ModConfig.Enabled.Value=true;Scope.Tick();Vector(new(2,2,1),b.transform.localScale);Vector(new(.5f,.5f,1),b._container.localScale);});
  Test("RecalcPosition offsets once in non-Greek and never when disabled",()=>{World(1);var b=Bag();b.transform.position=new(4,5,6);BagPatch.RecalcPosition_Postfix(b);Vector(new(7.7f,3.5f,6),b.transform.position);BagPatch.StartShow_Postfix(b);Vector(new(7.7f,3.5f,6),b.transform.position);ModConfig.Enabled.Value=false;Scope.Tick();b.transform.position=new(4,5,6);BagPatch.RecalcPosition_Postfix(b);Vector(new(4,5,6),b.transform.position);});
  Test("StartShow notification does not reapply legacy position offset",()=>{var b=Bag();b.transform.position=new(4,5,6);BagPatch.StartShow_Postfix(b);Vector(new(4,5,6),b.transform.position);});
  Test("REVIEW same coin moved to different native container restores its current composition",()=>{var a=Bag();ScaleBag(a);var c=Coin(a,new(2,2,1));Reset(c);var b=Bag(nativeContainer:new(2,2,1));ScaleBag(b);c.bag=b;c.transform.localScale=new(1,1,1);Reset(c);Vector(new(.5f,.5f,1),c.transform.localScale);ModConfig.Enabled.Value=false;Scope.Tick();Vector(new(.5f,.5f,1),c.transform.localScale);});
  Test("REVIEW external coin axes survive off-on replay",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));Reset(c);c.transform.localScale=new(1.7f,1.8f,1.9f);Reset(c);ModConfig.Enabled.Value=false;Scope.Tick();Vector(new(1.7f,1.8f,1.9f),c.transform.localScale);ModConfig.Enabled.Value=true;Scope.Tick();Vector(new(1.7f,1.8f,1.9f),c.transform.localScale);});
  Test("one-shot coin correction leaves no registry entry",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));int before=RegistryCount();Reset(c);Vector(Vector3.one,c.transform.localScale);Eq(before,RegistryCount(),"coin entry removed after correction");World(1);Eq(before,RegistryCount(),"no coin entry after world change");for(int i=0;i<3;i++){ModConfig.Enabled.Value=false;Scope.Tick();ModConfig.Enabled.Value=true;Scope.Tick();Eq(before,RegistryCount(),"registry stable after off-on");Vector(Vector3.one,c.transform.localScale);}});
  Test("fresh proof after an external coin write re-claims once",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));Reset(c);c.transform.localScale=new(1.7f,1.8f,1.9f);Reset(c);Vector(new(1.7f,1.8f,1.9f),c.transform.localScale);c.transform.localScale=new(2,2,1);Reset(c);Vector(Vector3.one,c.transform.localScale);ModConfig.Enabled.Value=false;Scope.Tick();Vector(Vector3.one,c.transform.localScale);ModConfig.Enabled.Value=true;Scope.Tick();Vector(Vector3.one,c.transform.localScale);});
  Test("per-axis external coin writes survive disable and enable",()=>{var b=Bag();ScaleBag(b);var c=Coin(b,new(2,2,1));Reset(c);c.transform.localScale=new(1.7f,1f,1f);ModConfig.Enabled.Value=false;Scope.Tick();ModConfig.Enabled.Value=true;Scope.Tick();Vector(new(1.7f,1f,1f),c.transform.localScale);c.transform.localScale=new(1f,1.8f,1f);ModConfig.Enabled.Value=false;Scope.Tick();ModConfig.Enabled.Value=true;Scope.Tick();Vector(new(1f,1.8f,1f),c.transform.localScale);c.transform.localScale=new(1f,1f,1.9f);ModConfig.Enabled.Value=false;Scope.Tick();ModConfig.Enabled.Value=true;Scope.Tick();Vector(new(1f,1f,1.9f),c.transform.localScale);});
  Console.WriteLine($"RESULT {passed} passed, {failed} failed");Environment.ExitCode=failed==0?0:1;
 }
}
